const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(
    new Cesium.OpenStreetMapImageryProvider({ url: 'https://tile.openstreetmap.org/', maximumLevel: 18 })
  ),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

viewer.scene.globe.enableLighting = false;

const cities = [
  { name: 'Los Angeles',  lon: -118.2437, lat: 34.0522 },
  { name: 'Denver',       lon: -104.9903, lat: 39.7392 },
  { name: 'Chicago',      lon:  -87.6298, lat: 41.8781 },
  { name: 'New York',     lon:  -74.0060, lat: 40.7128 },
];

// Draw ground-clamped red polyline connecting all four cities
const routePositions = Cesium.Cartesian3.fromDegreesArray(
  cities.flatMap(c => [c.lon, c.lat])
);

viewer.entities.add({
  polyline: {
    positions: routePositions,
    width: 10,
    material: new Cesium.PolylineGlowMaterialProperty({
      glowPower: 0.3,
      color: Cesium.Color.RED,
    }),
    clampToGround: true,
  },
});

// Add a solid red underline for maximum contrast
viewer.entities.add({
  polyline: {
    positions: routePositions,
    width: 5,
    material: Cesium.Color.fromCssColorString('#ff0000'),
    clampToGround: true,
  },
});

// Add labeled points at each city
for (const city of cities) {
  viewer.entities.add({
    position: Cesium.Cartesian3.fromDegrees(city.lon, city.lat),
    point: {
      pixelSize: 16,
      color: Cesium.Color.RED,
      outlineColor: Cesium.Color.WHITE,
      outlineWidth: 3,
      heightReference: Cesium.HeightReference.CLAMP_TO_GROUND,
      disableDepthTestDistance: Number.POSITIVE_INFINITY,
    },
    label: {
      text: city.name,
      font: 'bold 16px sans-serif',
      fillColor: Cesium.Color.WHITE,
      outlineColor: Cesium.Color.BLACK,
      outlineWidth: 3,
      style: Cesium.LabelStyle.FILL_AND_OUTLINE,
      verticalOrigin: Cesium.VerticalOrigin.BOTTOM,
      pixelOffset: new Cesium.Cartesian2(0, -22),
      heightReference: Cesium.HeightReference.CLAMP_TO_GROUND,
      disableDepthTestDistance: Number.POSITIVE_INFINITY,
    },
  });
}

// Frame camera top-down over continental US so the full route is visible
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(-96.1, 38.5, 4800000),
  orientation: {
    heading: Cesium.Math.toRadians(0),
    pitch: Cesium.Math.toRadians(-90),
    roll: 0,
  },
});
